package cn.local.psqirecord;

import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import org.json.*;
import java.util.*;

public final class Store extends SQLiteOpenHelper {
 private SQLiteDatabase upgradeDb;
 private SQLiteDatabase dbRead(){return upgradeDb==null?getReadableDatabase():upgradeDb;}
 private SQLiteDatabase dbWrite(){return upgradeDb==null?getWritableDatabase():upgradeDb;}
 public static final class Row {public String id,data;public long created,updated;public boolean deleted;}
 public Store(Context c){this(c,"psqi-records.db");}
 public Store(Context c,String name){super(c,name,null,4);}
 @Override public void onConfigure(SQLiteDatabase db){db.setForeignKeyConstraintsEnabled(true);db.execSQL("PRAGMA synchronous=FULL");}
 @Override public void onCreate(SQLiteDatabase db){
  db.execSQL("CREATE TABLE records(id TEXT PRIMARY KEY, data TEXT NOT NULL, created INTEGER NOT NULL, updated INTEGER NOT NULL, deleted INTEGER NOT NULL DEFAULT 0)");
  db.execSQL("CREATE TABLE revisions(seq INTEGER PRIMARY KEY AUTOINCREMENT,record_id TEXT NOT NULL REFERENCES records(id),data TEXT NOT NULL,reason TEXT NOT NULL,created INTEGER NOT NULL)");
  db.execSQL("CREATE INDEX rev_record ON revisions(record_id,seq)");
  db.execSQL("CREATE TABLE imports(fingerprint TEXT PRIMARY KEY)");
  patientSchema(db);
 }
 @Override public void onUpgrade(SQLiteDatabase d,int old,int next){if(old>=1&&old<4&&next==4){upgradeDb=d;try{if(old==1){patientSchema(d);backfill(d);}else{if(old==2)d.execSQL("ALTER TABLE record_meta ADD COLUMN scale TEXT NOT NULL DEFAULT 'PSQI'");boolean hasDeleted=false;try(Cursor c=d.rawQuery("PRAGMA table_info(patients)",null)){while(c.moveToNext())if(c.getString(1).equals("deleted"))hasDeleted=true;}if(!hasDeleted)d.execSQL("ALTER TABLE patients ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0");}d.execSQL("CREATE INDEX IF NOT EXISTS patient_scale_days ON record_meta(patient_id,day,scale)");}catch(Exception e){throw new IllegalStateException("数据升级未完成，原数据将保留",e);}finally{upgradeDb=null;}}else throw new IllegalStateException("不支持此数据库升级路径，请保留原安装");}
 public static String scaleOf(String data)throws Exception{return new JSONObject(data).optString("scale","PSQI");}
 public static JSONObject payload(Map<String,String>a,boolean completed)throws Exception{return payload(a,completed,"PSQI");}
 public static JSONObject payload(Map<String,String>a,boolean completed,String scale)throws Exception{
  Scales.Def d=Scales.get(scale);JSONObject j=new JSONObject();j.put("scale",scale);j.put("period",d.period);j.put("answers",new JSONObject(a));j.put("completed",completed);j.put("rule",d.rule);
  if(completed){int[]scores=Scales.score(scale,a);JSONArray values=new JSONArray();for(int n:scores)values.put(n);j.put("scores",values);j.put("total",Form.total(scores));}return j;
 }
 public static Map<String,String> answers(String data)throws Exception{String scale=scaleOf(data);JSONObject j=new JSONObject(data).getJSONObject("answers");Map<String,String>a=Scales.empty(scale);for(String k:Scales.keys(scale))a.put(k,j.optString(k,""));return a;}
 public static boolean completed(String data)throws Exception{return new JSONObject(data).getBoolean("completed");}
 public String create()throws Exception{String id=UUID.randomUUID().toString();long now=System.currentTimeMillis();String data=payload(Form.empty(),false).toString();SQLiteDatabase db=dbWrite();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("id",id);v.put("data",data);v.put("created",now);v.put("updated",now);v.put("deleted",0);db.insertOrThrow("records",null,v);revision(db,id,data,"新建草稿",now);db.setTransactionSuccessful();}finally{db.endTransaction();}return id;}
 private void revision(SQLiteDatabase db,String id,String data,String reason,long now){ContentValues r=new ContentValues();r.put("record_id",id);r.put("data",data);r.put("reason",reason);r.put("created",now);db.insertOrThrow("revisions",null,r);}
 public void save(String id,String data,String reason)throws Exception{validatePayload(data);SQLiteDatabase db=dbWrite();db.beginTransaction();try{requireActiveRecord(id);Row old=get(id);if(old==null)throw new IllegalStateException("记录不存在");if(!scaleOf(old.data).equals(scaleOf(data)))throw new IllegalArgumentException("不能更换已有记录的量表类型");if(!old.data.equals(data)){long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("data",data);v.put("updated",now);if(db.update("records",v,"id=?",new String[]{id})!=1)throw new IllegalStateException("保存失败");revision(db,id,data,reason,now);}ensureMeta(db,id);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public void trash(String id,boolean deleted)throws Exception{SQLiteDatabase db=dbWrite();db.beginTransaction();try{requireActiveRecord(id);Row row=get(id);if(row==null)throw new IllegalStateException("记录不存在");long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("deleted",deleted?1:0);v.put("updated",now);db.update("records",v,"id=?",new String[]{id});revision(db,id,row.data,deleted?"移入回收站":"从回收站恢复",now);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 private Row row(Cursor c){Row r=new Row();r.id=c.getString(0);r.data=c.getString(1);r.created=c.getLong(2);r.updated=c.getLong(3);r.deleted=c.getInt(4)!=0;return r;}
 public Row get(String id){try(Cursor c=dbRead().rawQuery("SELECT id,data,created,updated,deleted FROM records WHERE id=?",new String[]{id})){return c.moveToFirst()?row(c):null;}}
 public List<Row> rows(boolean deleted){List<Row>a=new ArrayList<>();try(Cursor c=dbRead().rawQuery("SELECT id,data,created,updated,deleted FROM records WHERE deleted=? AND NOT EXISTS (SELECT 1 FROM record_meta m JOIN patients p ON p.id=m.patient_id WHERE m.record_id=records.id AND p.deleted=1) ORDER BY updated DESC",new String[]{deleted?"1":"0"})){while(c.moveToNext())a.add(row(c));}return a;}
 public long revisionCount(){try(Cursor c=dbRead().rawQuery("SELECT COALESCE(SUM(seq),0) FROM sqlite_sequence WHERE name IN ('revisions','patient_events','meta_events')",null)){c.moveToFirst();return c.getLong(0);}}
 public JSONArray history(String id)throws Exception{JSONArray a=new JSONArray();try(Cursor c=dbRead().rawQuery("SELECT data,reason,created FROM revisions WHERE record_id=? ORDER BY seq DESC LIMIT 50",new String[]{id})){while(c.moveToNext()){JSONObject j=new JSONObject();j.put("data",new JSONObject(c.getString(0)));j.put("reason",c.getString(1));j.put("created",c.getLong(2));a.put(j);}}return a;}
 public JSONObject backup()throws Exception{
  SQLiteDatabase db=dbRead();db.beginTransaction();try{backfill(db);JSONObject out=new JSONObject();out.put("format","psqi-backup");out.put("version",4);out.put("appVersion","0.0.1");out.put("patients",patientBackup());out.put("rule",Form.RULE);out.put("exportedAt",System.currentTimeMillis());out.put("revision",revisionCount());JSONArray records=new JSONArray();
   try(Cursor c=db.rawQuery("SELECT id,data,created,updated,deleted FROM records ORDER BY created",null)){while(c.moveToNext()){Row r=row(c);JSONObject j=new JSONObject();j.put("id",r.id);j.put("data",new JSONObject(r.data));j.put("created",r.created);j.put("updated",r.updated);j.put("deleted",r.deleted);RecordMeta m=meta(r.id);j.put("patientId",m.patientId);j.put("day",m.day);j.put("scale",m.scale);j.put("dateHistory",metaBackup(r.id));JSONArray history=new JSONArray();try(Cursor h=db.rawQuery("SELECT data,reason,created FROM revisions WHERE record_id=? ORDER BY seq",new String[]{r.id})){while(h.moveToNext()){JSONObject v=new JSONObject();v.put("data",new JSONObject(h.getString(0)));v.put("reason",h.getString(1));v.put("created",h.getLong(2));history.put(v);}}j.put("history",history);records.put(j);}}
   out.put("records",records);db.setTransactionSuccessful();return out;
  }finally{db.endTransaction();}
 }
 public static void validatePayload(String data)throws Exception{
  if(data.length()>100000)throw new IllegalArgumentException("单份记录过大");JSONObject j=new JSONObject(data);String scale=scaleOf(data);Scales.Def d=Scales.get(scale);if(!d.rule.equals(j.getString("rule")))throw new IllegalArgumentException("不支持这个计分规则版本");JSONObject values=j.getJSONObject("answers");Set<String>allowed=new HashSet<>(Scales.keys(scale));Iterator<String>it=values.keys();while(it.hasNext())if(!allowed.contains(it.next()))throw new IllegalArgumentException("备份包含未知字段");for(String k:allowed){Object value=values.get(k);if(!(value instanceof String)||((String)value).length()>4000)throw new IllegalArgumentException("备份答案格式有误");}Object done=j.get("completed");if(!(done instanceof Boolean))throw new IllegalArgumentException("完成标记无效");if((Boolean)done){int[]scores=Scales.score(scale,answers(data));JSONArray saved=j.getJSONArray("scores");if(saved.length()!=scores.length||j.getInt("total")!=Form.total(scores))throw new IllegalArgumentException("备份分数与答案不一致");for(int n=0;n<scores.length;n++)if(saved.getInt(n)!=scores[n])throw new IllegalArgumentException("备份分数与答案不一致");}
 }
 public static void validateBackup(JSONObject root)throws Exception{
  if(!"psqi-backup".equals(root.getString("format"))||(root.getInt("version")<1||root.getInt("version")>4))throw new IllegalArgumentException("备份版本不受支持");validatePatients(root);JSONArray a=root.getJSONArray("records");if(a.length()>50000)throw new IllegalArgumentException("记录数过大");Set<String>ids=new HashSet<>();int count=0;
  for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);String id=r.getString("id");UUID.fromString(id);if(!ids.add(id))throw new IllegalArgumentException("备份包含重复记录编号");validatePayload(r.getJSONObject("data").toString());String recordScale=scaleOf(r.getJSONObject("data").toString());if(root.getInt("version")<3&&!recordScale.equals("PSQI"))throw new IllegalArgumentException("旧备份版本不能含新量表");if(root.getInt("version")>=3&&!r.getString("scale").equals(recordScale))throw new IllegalArgumentException("量表关联不一致");if(r.getLong("created")<=0||r.getLong("updated")<r.getLong("created"))throw new IllegalArgumentException("记录时间无效");if(!(r.get("deleted") instanceof Boolean))throw new IllegalArgumentException("删除标记无效");JSONArray h=r.getJSONArray("history");if((count+=h.length())>500000)throw new IllegalArgumentException("历史记录过多");for(int n=0;n<h.length();n++){JSONObject v=h.getJSONObject(n);validatePayload(v.getJSONObject("data").toString());if(!scaleOf(v.getJSONObject("data").toString()).equals(recordScale))throw new IllegalArgumentException("记录历史的量表类型不一致");if(v.getString("reason").length()>200||v.getLong("created")<=0)throw new IllegalArgumentException("历史记录格式有误");}}
 }
 public int[] restore(JSONObject root)throws Exception{
  validateBackup(root);int added=0,skipped=0,copies=0;SQLiteDatabase db=dbWrite();db.beginTransaction();try{Map<String,String>patientMap=restorePatients(db,root);JSONArray a=root.getJSONArray("records");for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);String oldId=r.getString("id"),id=oldId,data=r.getJSONObject("data").toString();String fingerprint=BackupFile.hash(r.toString());boolean seen;try(Cursor c=db.rawQuery("SELECT fingerprint FROM imports WHERE fingerprint=?",new String[]{fingerprint})){seen=c.moveToFirst();}Row existing=get(id);if(seen&&existing!=null){skipped++;continue;}
   if(existing!=null){id=UUID.randomUUID().toString();copies++;}
   ContentValues v=new ContentValues();v.put("id",id);v.put("data",data);v.put("created",r.getLong("created"));v.put("updated",r.getLong("updated"));v.put("deleted",r.getBoolean("deleted")?1:0);db.insertOrThrow("records",null,v);
   if(root.getInt("version")>=2){String pid=patientMap.get(r.getString("patientId"));JSONArray dates=r.getJSONArray("dateHistory");for(int k=0;k<dates.length();k++){JSONObject e=dates.getJSONObject(k);ContentValues hv=new ContentValues();hv.put("record_id",id);hv.put("patient_id",patientMap.get(e.getString("patientId")));hv.put("day",e.getString("day"));hv.put("reason",e.getString("reason"));hv.put("created",e.getLong("created"));db.insertOrThrow("meta_events",null,hv);}linkRecord(db,id,pid,r.getString("day"),"从备份恢复日期关联");}else ensureMeta(db,id);
   JSONArray h=r.getJSONArray("history");for(int n=0;n<h.length();n++){JSONObject rev=h.getJSONObject(n);revision(db,id,rev.getJSONObject("data").toString(),rev.getString("reason"),rev.getLong("created"));}revision(db,id,data,existing==null?"从备份恢复":"恢复副本（保留手机原记录）",System.currentTimeMillis());ContentValues mark=new ContentValues();mark.put("fingerprint",fingerprint);db.insertWithOnConflict("imports",null,mark,SQLiteDatabase.CONFLICT_IGNORE);added++;
  }db.setTransactionSuccessful();}finally{db.endTransaction();}return new int[]{added,skipped,copies};
 }
 public static final class Patient {public String id,code,name;public long created,updated;public boolean deleted;}
 public static final class RecordMeta {public String patientId,day,scale;}
 public static String day(long millis){return new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date(millis));}
 public static String today(){return day(System.currentTimeMillis());}
 public static void checkDay(String value){if(!value.matches("\\d{4}-\\d{2}-\\d{2}"))throw new IllegalArgumentException("日期格式应为 yyyy-MM-dd");java.time.LocalDate.parse(value);}
 private void patientSchema(SQLiteDatabase db){
  db.execSQL("CREATE TABLE patients(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0)");
  db.execSQL("CREATE TABLE patient_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,patient_id TEXT NOT NULL REFERENCES patients(id),data TEXT NOT NULL,reason TEXT NOT NULL,created INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE record_meta(record_id TEXT PRIMARY KEY REFERENCES records(id),patient_id TEXT NOT NULL REFERENCES patients(id),day TEXT NOT NULL,scale TEXT NOT NULL DEFAULT 'PSQI')");
  db.execSQL("CREATE INDEX patient_days ON record_meta(patient_id,day)");
  db.execSQL("CREATE TABLE meta_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,record_id TEXT NOT NULL REFERENCES records(id),patient_id TEXT NOT NULL REFERENCES patients(id),day TEXT NOT NULL,reason TEXT NOT NULL,created INTEGER NOT NULL)");
 }
 private Patient patientRow(Cursor c){Patient p=new Patient();p.id=c.getString(0);p.code=c.getString(1);p.name=c.getString(2);p.created=c.getLong(3);p.updated=c.getLong(4);p.deleted=c.getInt(5)!=0;return p;}
 public Patient patient(String id){try(Cursor c=dbRead().rawQuery("SELECT id,code,name,created,updated,deleted FROM patients WHERE id=?",new String[]{id})){return c.moveToFirst()?patientRow(c):null;}}
 private Patient patientByCode(String code){try(Cursor c=dbRead().rawQuery("SELECT id,code,name,created,updated,deleted FROM patients WHERE code=?",new String[]{code})){return c.moveToFirst()?patientRow(c):null;}}
 public List<Patient> patients(){return patients(false);}
 public List<Patient> patients(boolean deleted){List<Patient>out=new ArrayList<>();try(Cursor c=dbRead().rawQuery("SELECT p.id,p.code,p.name,p.created,p.updated,p.deleted FROM patients p WHERE p.deleted=? ORDER BY COALESCE((SELECT MAX(day) FROM record_meta m JOIN records r ON r.id=m.record_id WHERE m.patient_id=p.id AND r.deleted=0),'') DESC,p.created DESC",new String[]{deleted?"1":"0"})){while(c.moveToNext())out.add(patientRow(c));}return out;}
 private void patientEvent(SQLiteDatabase db,String id,String data,String reason,long created){ContentValues v=new ContentValues();v.put("patient_id",id);v.put("data",data);v.put("reason",reason);v.put("created",created);db.insertOrThrow("patient_events",null,v);}
 private JSONObject patientData(Patient p)throws Exception{JSONObject j=new JSONObject();j.put("code",p.code);j.put("name",p.name);j.put("deleted",p.deleted);return j;}
 public String addPatient(String code,String name)throws Exception{code=code.trim();name=name.trim();if(code.isEmpty()||code.length()>100||name.length()>100)throw new IllegalArgumentException("编号必填，编号与姓名最多100字");SQLiteDatabase d=dbWrite();d.beginTransaction();try{Patient previous=patientByCode(code);if(previous!=null)throw new IllegalArgumentException(previous.deleted?"这个编号在回收站，请先恢复病人档案":"这个编号已有档案，请从列表打开");String id=UUID.randomUUID().toString();long now=System.currentTimeMillis();insertPatient(d,id,code,name,now,now);patientEvent(d,id,patientData(patient(id)).toString(),"添加病人",now);d.setTransactionSuccessful();return id;}finally{d.endTransaction();}}
 private void insertPatient(SQLiteDatabase d,String id,String code,String name,long created,long updated){ContentValues v=new ContentValues();v.put("id",id);v.put("code",code);v.put("name",name);v.put("created",created);v.put("updated",updated);d.insertOrThrow("patients",null,v);}
 public void renamePatient(String id,String name)throws Exception{if(name.length()>100)throw new IllegalArgumentException("姓名或称呼最多100字");SQLiteDatabase d=dbWrite();d.beginTransaction();try{Patient p=patient(id);if(p==null||p.deleted)throw new IllegalArgumentException("档案不存在或在回收站，请先恢复");if(!p.name.equals(name)){p.name=name;long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("name",name);v.put("updated",now);d.update("patients",v,"id=?",new String[]{id});patientEvent(d,id,patientData(p).toString(),"修改姓名或称呼",now);}d.setTransactionSuccessful();}finally{d.endTransaction();}}
 public void trashPatient(String pid,boolean deleted)throws Exception{SQLiteDatabase d=dbWrite();d.beginTransaction();try{Patient p=patient(pid);if(p==null)throw new IllegalArgumentException("病人档案不存在");if(p.deleted!=deleted){ContentValues v=new ContentValues();long now=System.currentTimeMillis();v.put("deleted",deleted?1:0);v.put("updated",now);d.update("patients",v,"id=?",new String[]{pid});p.deleted=deleted;patientEvent(d,pid,patientData(p).toString(),deleted?"整个病人移入回收站":"恢复整个病人",now);}d.setTransactionSuccessful();}finally{d.endTransaction();}}
 private void requireActiveRecord(String id){RecordMeta m=meta(id);if(m!=null&&patient(m.patientId).deleted)throw new IllegalStateException("病人在回收站，请先恢复整个病人");}
 public void deleteRecord(String id)throws Exception{SQLiteDatabase d=dbWrite();d.beginTransaction();try{requireActiveRecord(id);Row r=get(id);if(r==null||!r.deleted)throw new IllegalArgumentException("请先将记录移入回收站");revision(d,id,r.data,"永久删除回收站记录",System.currentTimeMillis());d.delete("revisions","record_id=?",new String[]{id});d.delete("meta_events","record_id=?",new String[]{id});d.delete("record_meta","record_id=?",new String[]{id});d.delete("records","id=?",new String[]{id});d.setTransactionSuccessful();}finally{d.endTransaction();}}
 // One transaction removes a single patient, including trashed records and every revision.
 public int deletePatient(String pid)throws Exception{SQLiteDatabase d=dbWrite();d.beginTransaction();try{
  if(patient(pid)==null||!patient(pid).deleted)throw new IllegalArgumentException("请先将病人移入回收站，再永久删除");
  List<Row>owned=patientRecords(pid,false);owned.addAll(patientRecords(pid,true));
  // Reserve a monotonic change number before removing the event itself. No identifying tombstone remains.
  patientEvent(d,pid,"{}","删除整个病人",System.currentTimeMillis());
  for(Row r:owned){String[]id={r.id};d.delete("revisions","record_id=?",id);d.delete("meta_events","record_id=?",id);d.delete("record_meta","record_id=?",id);d.delete("records","id=?",id);}
  d.delete("meta_events","patient_id=?",new String[]{pid});d.delete("patient_events","patient_id=?",new String[]{pid});
  if(d.delete("patients","id=?",new String[]{pid})!=1)throw new IllegalStateException("删除未完成");
  d.setTransactionSuccessful();return owned.size();
 }finally{d.endTransaction();}}
 private String ensurePatient(String code,String recordId)throws Exception{code=code.trim();if(code.isEmpty())code="待核对-"+recordId;Patient p=patientByCode(code);return p==null?addPatient(code,""):p.id;}
 private void linkRecord(SQLiteDatabase db,String record,String pid,String date,String reason)throws Exception{ContentValues v=new ContentValues();v.put("record_id",record);v.put("patient_id",pid);v.put("day",date);v.put("scale",scaleOf(get(record).data));db.insertWithOnConflict("record_meta",null,v,SQLiteDatabase.CONFLICT_REPLACE);ContentValues h=new ContentValues(v);h.remove("scale");h.put("reason",reason);h.put("created",System.currentTimeMillis());db.insertOrThrow("meta_events",null,h);}
 public RecordMeta meta(String id){try(Cursor c=dbRead().rawQuery("SELECT patient_id,day,scale FROM record_meta WHERE record_id=?",new String[]{id})){if(!c.moveToFirst())return null;RecordMeta m=new RecordMeta();m.patientId=c.getString(0);m.day=c.getString(1);m.scale=c.getString(2);return m;}}
 private void ensureMeta(SQLiteDatabase db,String id)throws Exception{if(meta(id)!=null)return;Row r=get(id);linkRecord(db,id,ensurePatient(answers(r.data).get("patient"),id),day(r.created),"按原创建日期归档");}
 private void backfill(SQLiteDatabase db)throws Exception{List<String>ids=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT r.id FROM records r LEFT JOIN record_meta m ON m.record_id=r.id WHERE m.record_id IS NULL",null)){while(c.moveToNext())ids.add(c.getString(0));}for(String id:ids)ensureMeta(db,id);}
 public List<Row> patientRecords(String pid,boolean deleted){List<Row>out=new ArrayList<>();try(Cursor c=dbRead().rawQuery("SELECT r.id,r.data,r.created,r.updated,r.deleted FROM records r JOIN record_meta m ON m.record_id=r.id WHERE m.patient_id=? AND r.deleted=? ORDER BY m.day DESC,r.updated DESC",new String[]{pid,deleted?"1":"0"})){while(c.moveToNext())out.add(row(c));}return out;}
 public String createForPatient(String pid,String date)throws Exception{return createForPatient(pid,date,"PSQI");}
 public String createForPatient(String pid,String date,String scale)throws Exception{Scales.get(scale);checkDay(date);SQLiteDatabase d=dbWrite();d.beginTransaction();try{Patient p=patient(pid);if(p==null||p.deleted)throw new IllegalArgumentException("病人档案不存在或在回收站，请先恢复");try(Cursor c=d.rawQuery("SELECT r.id,r.deleted FROM records r JOIN record_meta m ON m.record_id=r.id WHERE m.patient_id=? AND m.day=? AND m.scale=? ORDER BY r.deleted ASC,r.updated DESC",new String[]{pid,date,scale})){if(c.moveToFirst()){if(c.getInt(1)!=0)throw new IllegalArgumentException("这一天已有记录在回收站，请先恢复");String id=c.getString(0);d.setTransactionSuccessful();return id;}}
   String id=UUID.randomUUID().toString();long now=System.currentTimeMillis();Map<String,String>a=Scales.empty(scale);a.put("patient",p.code);if(!scale.equals("PSQI"))a.put("assessmentTime",new java.text.SimpleDateFormat("HH:mm",Locale.US).format(new Date()));String data=payload(a,false,scale).toString();ContentValues v=new ContentValues();v.put("id",id);v.put("data",data);v.put("created",now);v.put("updated",now);v.put("deleted",0);d.insertOrThrow("records",null,v);revision(d,id,data,"新建 "+date+" 记录",now);linkRecord(d,id,pid,date,"新建日期记录");d.setTransactionSuccessful();return id;
  }finally{d.endTransaction();}}
 public void setDate(String id,String date)throws Exception{checkDay(date);SQLiteDatabase d=dbWrite();d.beginTransaction();try{requireActiveRecord(id);RecordMeta m=meta(id);if(m==null)throw new IllegalArgumentException("记录缺少档案关联");if(!date.equals(m.day)){try(Cursor c=d.rawQuery("SELECT r.id FROM records r JOIN record_meta m ON m.record_id=r.id WHERE m.patient_id=? AND m.day=? AND m.scale=? AND r.id<>?",new String[]{m.patientId,date,m.scale,id})){if(c.moveToFirst())throw new IllegalArgumentException("这个日期已有记录（含回收站），不能覆盖");}linkRecord(d,id,m.patientId,date,"记录日期从 "+m.day+" 调整到 "+date);ContentValues v=new ContentValues();v.put("updated",System.currentTimeMillis());d.update("records",v,"id=?",new String[]{id});revision(d,id,get(id).data,"日期调整 "+m.day+" → "+date,System.currentTimeMillis());}d.setTransactionSuccessful();}finally{d.endTransaction();}}
 private JSONArray patientBackup()throws Exception{JSONArray out=new JSONArray();List<Patient>all=patients(false);all.addAll(patients(true));for(Patient p:all){JSONObject j=new JSONObject();j.put("id",p.id);j.put("code",p.code);j.put("name",p.name);j.put("created",p.created);j.put("updated",p.updated);j.put("deleted",p.deleted);JSONArray h=new JSONArray();try(Cursor c=dbRead().rawQuery("SELECT data,reason,created FROM patient_events WHERE patient_id=? ORDER BY seq",new String[]{p.id})){while(c.moveToNext()){JSONObject e=new JSONObject();e.put("data",new JSONObject(c.getString(0)));e.put("reason",c.getString(1));e.put("created",c.getLong(2));h.put(e);}}j.put("history",h);out.put(j);}return out;}
 private JSONArray metaBackup(String id)throws Exception{JSONArray out=new JSONArray();try(Cursor c=dbRead().rawQuery("SELECT patient_id,day,reason,created FROM meta_events WHERE record_id=? ORDER BY seq",new String[]{id})){while(c.moveToNext()){JSONObject j=new JSONObject();j.put("patientId",c.getString(0));j.put("day",c.getString(1));j.put("reason",c.getString(2));j.put("created",c.getLong(3));out.put(j);}}return out;}
 private static void validatePatients(JSONObject root)throws Exception{if(root.getInt("version")==1)return;JSONArray people=root.getJSONArray("patients");if(people.length()>50000)throw new IllegalArgumentException("档案数过多");Set<String>ids=new HashSet<>(),codes=new HashSet<>();for(int n=0;n<people.length();n++){JSONObject p=people.getJSONObject(n);String id=p.getString("id"),code=p.getString("code");if(root.getInt("version")>=4&&!(p.get("deleted") instanceof Boolean))throw new IllegalArgumentException("病人回收站标记无效");UUID.fromString(id);if(!ids.add(id)||!codes.add(code)||code.trim().isEmpty()||code.length()>100||p.getString("name").length()>100||p.getLong("created")<=0||p.getLong("updated")<p.getLong("created"))throw new IllegalArgumentException("病人档案格式有误");JSONArray h=p.getJSONArray("history");for(int k=0;k<h.length();k++){JSONObject e=h.getJSONObject(k);if(e.getJSONObject("data").getString("code").length()>100||e.getJSONObject("data").getString("name").length()>100||e.getString("reason").length()>200||e.getLong("created")<=0)throw new IllegalArgumentException("档案历史有误");}}
  JSONArray records=root.getJSONArray("records");for(int n=0;n<records.length();n++){JSONObject r=records.getJSONObject(n);if(!ids.contains(r.getString("patientId")))throw new IllegalArgumentException("记录关联的病人档案不存在");checkDay(r.getString("day"));JSONArray h=r.getJSONArray("dateHistory");for(int k=0;k<h.length();k++){JSONObject e=h.getJSONObject(k);if(!ids.contains(e.getString("patientId"))||e.getString("reason").length()>200||e.getLong("created")<=0)throw new IllegalArgumentException("日期历史格式有误");checkDay(e.getString("day"));}}
 }
 private boolean wasImported(SQLiteDatabase db,String fp){try(Cursor c=db.rawQuery("SELECT fingerprint FROM imports WHERE fingerprint=?",new String[]{fp})){return c.moveToFirst();}}
 private void markImported(SQLiteDatabase db,String fp){ContentValues v=new ContentValues();v.put("fingerprint",fp);db.insertWithOnConflict("imports",null,v,SQLiteDatabase.CONFLICT_IGNORE);}
 private Map<String,String> restorePatients(SQLiteDatabase d,JSONObject root)throws Exception{Map<String,String>map=new HashMap<>();if(root.getInt("version")==1)return map;JSONArray people=root.getJSONArray("patients");for(int n=0;n<people.length();n++){JSONObject p=people.getJSONObject(n);String source=p.getString("id"),code=p.getString("code"),fingerprint="P:"+BackupFile.hash(p.toString());Patient existing=patient(source);if(existing!=null&&!existing.code.equals(code))existing=null;if(existing==null)existing=patientByCode(code);String target=existing==null?(patient(source)==null?source:UUID.randomUUID().toString()):existing.id;map.put(source,target);if(existing!=null&&wasImported(d,fingerprint))continue;if(existing==null){insertPatient(d,target,code,p.getString("name"),p.getLong("created"),p.getLong("updated"));if(root.getInt("version")>=4){ContentValues state=new ContentValues();state.put("deleted",p.getBoolean("deleted")?1:0);d.update("patients",state,"id=?",new String[]{target});}}JSONArray h=p.getJSONArray("history");for(int k=0;k<h.length();k++){JSONObject e=h.getJSONObject(k);patientEvent(d,target,e.getJSONObject("data").toString(),e.getString("reason"),e.getLong("created"));}JSONObject incoming=new JSONObject();incoming.put("code",code);incoming.put("name",p.getString("name"));patientEvent(d,target,incoming.toString(),existing==null?"从备份恢复档案":"备份档案留档（保留当前称呼）",System.currentTimeMillis());markImported(d,fingerprint);}return map;}

 public String csv()throws Exception{return Reports.csv(backup(),new Reports.Filter(null,"",""));}
}
